// Des: Tests for M9: geo and wait options per vendor adapter and ladder
// Flo: build requests with geo > assert vendor params, prices, ladder skip of own GET
// I/O: mock vendor + mock site > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const base = @import("nt-vend-base.zig"); const zenr = @import("nt-vend-zenr.zig"); const deco = @import("nt-vend-deco.zig"); const brig = @import("nt-vend-brig.zig"); const ladd = @import("ru-tier-ladd.zig"); const runz = @import("ct-ctrl-runz.zig"); const args = @import("ct-ctrl-args.zig"); const inde = @import("st-page-inde.zig"); const vmoc = @import("nt-vend-mock.zig"); const mock = @import("te-mock-serv.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
test "zenrows: geo adds premium proxy + proxy_country, wait and selector only with render" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const aaaz = aren.allocator(); const plai = try zenr.requBuil(aaaz, "K", .{ .urlz = "http://x.test/", .mode = .plai, .geoz = "us" }); try std.testing.expect(std.mem.indexOf(u8, plai.urlz, "&premium_proxy=true&proxy_country=us") != null); try std.testing.expect(std.mem.indexOf(u8, plai.urlz, "js_render") == null); const rend = try zenr.requBuil(aaaz, "K", .{ .urlz = "http://x.test/", .mode = .rend, .geoz = "de", .wait = 3000, .sele = "div.item" }); try std.testing.expect(std.mem.indexOf(u8, rend.urlz, "&js_render=true&premium_proxy=true&proxy_country=de&wait=3000&wait_for=div.item") != null); const noge = try zenr.requBuil(aaaz, "K", .{ .urlz = "http://x.test/", .mode = .plai, .wait = 500 }); try std.testing.expect(std.mem.indexOf(u8, noge.urlz, "wait=") == null); try std.testing.expectError(error.BadGeo, zenr.requBuil(aaaz, "K", .{ .urlz = "http://x.test/", .mode = .plai, .geoz = "usa" })); }
test "decodo: geo is the full country name, unknown code is refused" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const aaaz = aren.allocator(); const http = try deco.requBuil(aaaz, "K", .{ .urlz = "http://x.test/", .mode = .rend, .geoz = "gb" }); try std.testing.expect(std.mem.indexOf(u8, http.body, "\"geo\":\"United Kingdom\"") != null); const none = try deco.requBuil(aaaz, "K", .{ .urlz = "http://x.test/", .mode = .plai }); try std.testing.expect(std.mem.indexOf(u8, none.body, "geo") == null); try std.testing.expectError(error.BadGeo, deco.requBuil(aaaz, "K", .{ .urlz = "http://x.test/", .mode = .plai, .geoz = "zz" })); }
test "bright data: country is lowercase ISO-2, absent without geo" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const aaaz = aren.allocator(); const http = try brig.requBuil(aaaz, "K", "zone1", .{ .urlz = "http://x.test/", .mode = .plai, .geoz = "FR" }); try std.testing.expect(std.mem.indexOf(u8, http.body, "\"country\":\"fr\"") != null); const none = try brig.requBuil(aaaz, "K", "zone1", .{ .urlz = "http://x.test/", .mode = .plai }); try std.testing.expect(std.mem.indexOf(u8, none.body, "country") == null); }
test "geo price: zenrows geo = premium cost, others unchanged" { try std.testing.expectEqual(@as(u32, 10), base.credRequ(.zenr, .{ .urlz = "", .mode = .plai, .geoz = "us" })); try std.testing.expectEqual(@as(u32, 25), base.credRequ(.zenr, .{ .urlz = "", .mode = .rend, .geoz = "us" })); try std.testing.expectEqual(@as(u32, 5), base.credRequ(.zenr, .{ .urlz = "", .mode = .rend })); try std.testing.expectEqual(@as(u32, 2), base.credRequ(.deco, .{ .urlz = "", .mode = .rend, .geoz = "us" })); }
test "dry-run worst case shows the premium price when geo is set" { var conf: cfgz.Conf = .{}; conf.vend_orde = &.{"zenr"}; const free = runz.estzWors(conf, ""); const geo = runz.estzWors(conf, "us"); try std.testing.expect(geo.cred > free.cred); }
test "cli flags --geoz and --wait parse, bad code is usage error" { const got2 = try args.argsRead(&.{ "fetch", "http://x.test/", "--geoz", "us", "--wait", "2000" }, std.testing.allocator); try std.testing.expectEqualStrings("us", got2.geoz); try std.testing.expectEqual(@as(u32, 2000), got2.wait); try std.testing.expectError(error.BadUsage, args.argsRead(&.{ "fetch", "http://x.test/", "--geoz", "usa" }, std.testing.allocator)); }
test "config: bad geo default is refused, host override parses" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try std.testing.expectError(error.BadConfig, cfgz.confPars(aren.allocator(), "{\"geoz_code_dflt\":\"usa\"}")); const conf = try cfgz.confPars(aren.allocator(), "{\"geoz_host_over\":{\"127.0.0.1\":\"jp\"}}"); try std.testing.expectEqualStrings("jp", conf.geoz_host_over.map.get("127.0.0.1").?); }
fn rich() cfgz.Conf { var conf: cfgz.Conf = .{}; conf.vend_free_cred = .{ .deco = 100, .zenr = 100, .brig = 100 }; return conf; }
test "ladder: geo skips own GET, reaches the vendor with the geo param, host override works" { const tmpz = std.testing.tmpDir(.{}); var tmzz = tmpz; defer tmzz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmzz.sub_path}); defer allo.free(dirz); var srv2: mock.Mock = undefined; try srv2.sta2(std.testing.io); defer srv2.halt(); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var vmkz = vmoc.Mock.init(allo); defer vmkz.deinit(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf4: [64]u8 = undefined; const urlz = srv2.urlzOfzz(&buf4, "/p1"); var ladz: ladd.Ladd = .{ .gpaz = allo, .iozz = std.testing.io, .conf = rich(), .dbzz = &dbzz, .dirz = dirz, .back = vmkz.bac2(), .priv = true, .geoz = "us" }; const out2 = try ladd.laddFetc(&ladz, aren.allocator(), urlz); try std.testing.expect(out2.tier >= 2); try std.testing.expectEqual(@as(u32, 0), srv2.hits.load(.monotonic)); try std.testing.expectEqualStrings("us", vmkz.cal3.items[0].geoz); var conf = rich(); var map: std.json.ArrayHashMap([]const u8) = .{}; defer map.deinit(aren.allocator()); try map.map.put(aren.allocator(), "127.0.0.1", "jp"); conf.geoz_host_over = map; ladz.conf = conf; ladz.geoz = ""; var buf2: [64]u8 = undefined; _ = try ladd.laddFetc(&ladz, aren.allocator(), srv2.urlzOfzz(&buf2, "/p2")); try std.testing.expectEqualStrings("jp", vmkz.cal3.items[vmkz.cal3.items.len - 1].geoz); try std.testing.expectEqual(@as(u32, 0), srv2.hits.load(.monotonic)); }
test "ladder: wait or selector forces render, plain is skipped" { const tmpz = std.testing.tmpDir(.{}); var tmzz = tmpz; defer tmzz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmzz.sub_path}); defer allo.free(dirz); var srv2: mock.Mock = undefined; try srv2.sta2(std.testing.io); defer srv2.halt(); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var vmkz = vmoc.Mock.init(allo); defer vmkz.deinit(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf4: [64]u8 = undefined; var ladz: ladd.Ladd = .{ .gpaz = allo, .iozz = std.testing.io, .conf = rich(), .dbzz = &dbzz, .dirz = dirz, .back = vmkz.bac2(), .priv = true, .wait = 1000 }; _ = try ladd.laddFetc(&ladz, aren.allocator(), srv2.urlzOfzz(&buf4, "/e403")); try std.testing.expect(vmkz.cal3.items[0].mode == .rend); try std.testing.expectEqual(@as(u32, 1000), vmkz.cal3.items[0].wait); }
